begin;

create table public."Dim_TipoJornal" (
  "Id_Tipo_Jornal" smallint generated by default as identity primary key,
  "Descripcion" character varying not null,
  estado smallint not null default 1 check (estado in (0, 1)),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public."Dim_TipoJornal" is
  'Catálogo de tipos de jornal para las labores finales de mano de obra.';
comment on column public."Dim_TipoJornal".estado is
  'Estado del registro: 1 activo, 0 inactivo.';

alter table public."Dim_TipoJornal" enable row level security;
revoke all on table public."Dim_TipoJornal" from public, anon, authenticated;
grant select, insert, update, delete on table public."Dim_TipoJornal" to authenticated;

create policy dim_tipo_jornal_select_admin on public."Dim_TipoJornal"
for select to authenticated using ((select private.is_admin()));
create policy dim_tipo_jornal_insert_admin on public."Dim_TipoJornal"
for insert to authenticated with check ((select private.is_admin()));
create policy dim_tipo_jornal_update_admin on public."Dim_TipoJornal"
for update to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy dim_tipo_jornal_delete_admin on public."Dim_TipoJornal"
for delete to authenticated using ((select private.is_admin()));

create or replace function private.set_dim_tipo_jornal_updated_at()
returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;
revoke all on function private.set_dim_tipo_jornal_updated_at() from public, anon, authenticated, service_role;

create trigger trg_dim_tipo_jornal_updated_at
before update on public."Dim_TipoJornal"
for each row execute function private.set_dim_tipo_jornal_updated_at();

insert into public."Dim_TipoJornal" ("Id_Tipo_Jornal", "Descripcion") values
  (1, 'Jornal Básico'),
  (2, 'Jornal Operador Maquinaria'),
  (3, 'Jefes de Campo o Administrativos');

select setval(
  pg_get_serial_sequence('public."Dim_TipoJornal"', 'Id_Tipo_Jornal'),
  (select max("Id_Tipo_Jornal") from public."Dim_TipoJornal"),
  true
);

do $$
declare
  v_sequence regclass := pg_get_serial_sequence('public."Dim_TipoJornal"', 'Id_Tipo_Jornal');
begin
  execute format('grant usage, select on sequence %s to authenticated', v_sequence);
end;
$$;

alter table public."Dim_Labor_Final"
  add constraint fk_dim_labor_final_tipo_jornal
  foreign key ("id_Tipo_Jornal")
  references public."Dim_TipoJornal" ("Id_Tipo_Jornal")
  on update cascade on delete restrict;

comment on column public."Dim_Labor_Final"."id_Tipo_Jornal" is
  'Tipo de jornal asociado a la labor final.';

commit;
